// === Uncler M Variant #1: Cyberpunk Holographic Globe & Beat Pulse ===
// Inspired by OpenProcessing 2955184 'Unusual Globe' by u110137

var num = 180;
var counter = 0;
var mode = 0;
var ang, tang;

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);
	colorMode(HSB, 360, 100, 100, 100);
	ang = createVector(0, 0, 0);
	tang = createVector(HALF_PI, 0, 0);
}

function windowResized() {
	resizeCanvas(windowWidth, windowHeight);
}

function draw() {
	let bEnergy = (window.beatEnergy || 0.0);
	let bassE = (window.bassEnergy || 0.0);
	let midE = (window.midEnergy || 0.0);
	let highE = (window.highEnergy || 0.0);

	counter += (1 + bassE * 3.0);
	if (frameCount % 120 === 0 && bEnergy > 0.4) {
		mode = (mode + 1) % 3;
	}

	tang.y = sin(frameCount * 0.015) * 1.5 + bassE * 0.5;
	tang.x = cos(frameCount * 0.012) * 1.2;
	ang.lerp(tang, 0.08);

	let m = 6 * TAU * cos(counter / 180) / num;
	orbitControl(0, 0, 0.5);
	rotateZ(ang.z + frameCount * 0.005);
	rotateY(ang.y);
	rotateX(ang.x);
	background(220, 80, 10);
	noFill();

	let scalePulse = 1.0 + bEnergy * 0.25;
	scale(scalePulse);

	for (let i = 0; i < min(num, frameCount); i++) {
		let a = i * PI / num;
		let baseR = sin(a) * min(width, height) / 2.3;
		let r = baseR * (1.0 + sin(i * 0.1 + frameCount * 0.05) * 0.05 * midE);

		// Cyberpunk Neon HSL palette
		let hueVal = (180 + i * 0.8 + bEnergy * 60) % 360;
		let satVal = 85 + sin(i * 0.05) * 15;
		let briVal = 80 + bEnergy * 20;
		stroke(hueVal, satVal, briVal, 75);
		strokeWeight(1.5 + (i % 3 === 0 ? 1.5 : 0) + highE * 2.0);

		push();
		switch (mode) {
			case 0:
				rotateZ(2 * (i - num / 2) * m);
				break;
			case 1:
				rotateZ((i < num / 2) * PI);
				rotateY((i - num / 2) * m);
				break;
			case 2:
				rotateZ((i < num / 2) * PI);
				rotateX((i - num / 2) * m);
				break;
		}
		translate(0, 0, cos(a) * min(width, height) / 2.5);
		arc(0, 0, r, r, 0, PI, OPEN, 36);
		pop();
	}
}

